29	function sseSetup(res: any) {
30	    res.setHeader('Content-Type', 'text/event-stream');
31	    res.setHeader('Cache-Control', 'no-cache');
32	    res.setHeader('Connection', 'keep-alive');
33	    res.setHeader('X-Accel-Buffering', 'no');
34	    res.flushHeaders();
35	    return (event: string, data: unknown) => {
36	        res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
37	    };
38	}
