1	import { NotebookService, DocType } from './notebookService';
2	
3	const OLLAMA_BASE = process.env.OLLAMA_BASE_URL || 'http://localhost:11434';
4	
5	const DOC_PROMPTS: Record<DocType, (text: string) => string> = {
6	    summary: (text) => `You are an expert analyst. Read the following source material and write a comprehensive executive summary in markdown. Include key findings, main themes, and critical insights. Use headings, bullet points, and clear structure.\n\n---\n${text.slice(0, 12000)}`,
7	
8	    study_guide: (text) => `You are an expert educator. Read the following material and create a detailed study guide in markdown with: ## Key Concepts (with definitions), ## Core Arguments, ## Important Facts, ## Potential Exam Questions with answers, ## Glossary of Terms.\n\n---\n${text.slice(0, 12000)}`,
9	
10	    faq: (text) => `You are a helpful assistant. Read the following material and generate a detailed FAQ document in markdown. Create 10-15 thoughtful questions a reader would ask, followed by thorough answers. Format as ## Q: ... and **A:** ...\n\n---\n${text.slice(0, 12000)}`,
11	
12	    timeline: (text) => `You are a historian and analyst. Read the following material and extract a chronological timeline of all events, dates, and milestones. Format as a markdown timeline with ## Year/Date headers and bullet points for each event. If no explicit dates, infer a logical sequence.\n\n---\n${text.slice(0, 12000)}`,
13	
14	    briefing: (text) => `You are an intelligence analyst. Create a concise executive briefing document from the following material. Include: ## Situation Overview (2-3 sentences), ## Key Points (5-7 bullets), ## Critical Risks or Concerns, ## Recommended Actions, ## Background Context. Be direct and actionable.\n\n---\n${text.slice(0, 12000)}`
15	};
16	
17	const DOC_TITLES: Record<DocType, string> = {
18	    summary: 'Executive Summary',
19	    study_guide: 'Study Guide',
20	    faq: 'FAQ Document',
21	    timeline: 'Timeline',
22	    briefing: 'Intelligence Briefing'
23	};
24	
25	export interface DocGenStreamOptions {
26	    notebookId: number;
27	    docType: DocType;
28	    modelId: string;
29	    onToken: (token: string) => void;
30	    onDone: (docId: number) => void;
31	    onError: (msg: string) => void;
32	    signal?: AbortSignal;
33	}
34	
35	export class NotebookDocGenService {
36	    private notebookService: NotebookService;
37	
38	    constructor(notebookService: NotebookService) {
39	        this.notebookService = notebookService;
40	    }
41	
42	    async streamGenerate(opts: DocGenStreamOptions): Promise<void> {
43	        const { notebookId, docType, modelId, onToken, onDone, onError, signal } = opts;
44	
45	        const sourceText = this.notebookService.getAllSourceText(notebookId);
46	        if (!sourceText.trim()) {
47	            onError('No source content found for this notebook. Add and process sources first.');
48	            return;
49	        }
50	
51	        const userPrompt = DOC_PROMPTS[docType](sourceText);
52	
53	        try {
54	            const upstream = await fetch(`${OLLAMA_BASE}/api/chat`, {
55	                method: 'POST',
56	                headers: { 'Content-Type': 'application/json' },
57	                body: JSON.stringify({
58	                    model: modelId,
59	                    messages: [{ role: 'user', content: userPrompt }],
60	                    stream: true
61	                }),
62	                signal
63	            });
64	
65	            if (!upstream.ok) throw new Error(`Ollama HTTP ${upstream.status}`);
66	            if (!upstream.body) throw new Error('No response body');
67	
68	            let fullContent = '';
69	            const reader = upstream.body.getReader();
70	            const decoder = new TextDecoder();
71	
72	            while (true) {
73	                const { done, value } = await reader.read();
74	                if (done) break;
75	                const text = decoder.decode(value, { stream: true });
76	                for (const line of text.split('\n').filter(Boolean)) {
77	                    try {
78	                        const parsed = JSON.parse(line);
79	                        const token = parsed?.message?.content || '';
80	                        if (token) {
81	                            fullContent += token;
82	                            onToken(token);
83	                        }
84	                        if (parsed?.done) break;
85	                    } catch (_) {}
86	                }
87	            }
88	
89	            if (!fullContent.trim()) throw new Error('Empty response from model');
90	
91	            const doc = this.notebookService.createDoc(
92	                notebookId, docType,
93	                DOC_TITLES[docType],
94	                fullContent,
95	                modelId
96	            );
97	            onDone(doc.id);
98	        } catch (e: any) {
99	            if (e.name !== 'AbortError') {
100	                onError(e.message || 'DOC_GEN_FAILED');
101	            }
102	        }
103	    }
104	}
