135	
136	export interface StreamCallbacks {
137	    onToken: (token: string) => void;
138	    onCitation: (citation: RagCitation) => void;
139	    onDone: (content: string) => void;
140	    onError: (msg: string) => void;
141	}
142	
143	export function streamChat(notebookId: number, query: string, model: string, callbacks: StreamCallbacks): EventSource {
144	    const url = `${API_ORIGINS[0]}/api/notebook/notebooks/${notebookId}/stream?command=${encodeURIComponent(query)}&model=${encodeURIComponent(model)}`;
145	    const es = new EventSource(url);
146	    let full = '';
147	
148	    es.addEventListener('token', (e: MessageEvent) => {
149	        try {
150	            const { token } = JSON.parse(e.data);
151	            full += token;
152	            callbacks.onToken(token);
153	        } catch (_) {}
154	    });
155	
156	    es.addEventListener('citation', (e: MessageEvent) => {
157	        try {
158	            callbacks.onCitation(JSON.parse(e.data));
159	        } catch (_) {}
160	    });
161	
162	    es.addEventListener('done', (e: MessageEvent) => {
163	        es.close();
164	        try { const { content } = JSON.parse(e.data); full = content || full; } catch (_) {}
165	        callbacks.onDone(full);
166	    });
167	
168	    es.addEventListener('error', (e: MessageEvent) => {
169	        es.close();
170	        let msg = 'STREAM_FAILED';
171	        try { msg = JSON.parse((e as any).data)?.message || msg; } catch (_) {}
172	        callbacks.onError(msg);
173	    });
174	
175	    es.onerror = () => { es.close(); callbacks.onError('CONNECTION_LOST'); };
176	
177	    return es;
178	}
