180	// ─── Document Generation ────────────────────────────────────────────────────
181	
182	export interface DocGenCallbacks {
183	    onToken: (token: string) => void;
184	    onDone: (docId: number) => void;
185	    onError: (msg: string) => void;
186	}
187	
188	export function streamGenerate(notebookId: number, docType: DocType, model: string, callbacks: DocGenCallbacks): EventSource {
189	    const url = `${API_ORIGINS[0]}/api/notebook/notebooks/${notebookId}/generate`;
190	    // POST with SSE isn't standard — we use fetch + ReadableStream here
191	    const es = new (class extends EventTarget {
192	        close() {}
193	    } as any)();
194	
195	    (async () => {
196	        try {
197	            const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/generate`, {
198	                method: 'POST',
199	                headers: { 'Content-Type': 'application/json' },
200	                body: JSON.stringify({ doc_type: docType, model_id: model })
201	            });
202	            if (!r.ok || !r.body) throw new Error(`HTTP ${r.status}`);
203	
204	            const reader = r.body.getReader();
205	            const decoder = new TextDecoder();
206	            let buffer = '';
207	
208	            while (true) {
209	                const { done, value } = await reader.read();
210	                if (done) break;
211	                buffer += decoder.decode(value, { stream: true });
212	                const lines = buffer.split('\n');
213	                buffer = lines.pop() || '';
214	                for (const line of lines) {
215	                    if (line.startsWith('event: token')) continue;
216	                    if (line.startsWith('data: ')) {
217	                        try {
218	                            const data = JSON.parse(line.slice(6));
219	                            if (data.token !== undefined) callbacks.onToken(data.token);
220	                            if (data.docId !== undefined) callbacks.onDone(data.docId);
221	                            if (data.message !== undefined) callbacks.onError(data.message);
222	                        } catch (_) {}
223	                    }
224	                }
225	            }
226	        } catch (e: any) {
227	            callbacks.onError(e.message || 'GENERATE_FAILED');
228	        }
229	    })();
230	
231	    return es;
232	}
